// The §11 wire fixtures (contract §11 row 1; be.md task 2): one committed JSON event per §4.3 rule, GENERATED by
// this suite into tests/fixtures/*.json and fed through `validation.ValidatePayload` + `mapping.MapPayloadToEvent`
// + protovalidate by tests/unit/sdk_js_fixture_test.go (root Go module, no build tag — decision 30). The Go side
// never needs node: the files are committed, and this suite rewrites one only when its content changed.
//
// Deterministic output: `crypto.randomUUID` and the clock are stubbed so a re-run leaves `git status` clean.
// Shuffle-safe: every test starts from a deleted `globalThis` slot.

import { readdirSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { captureException, captureMessage } from '../src/core/capture.js';
import { MAX_COMPONENT_STACK_BYTES, MAX_MESSAGE_BYTES, MAX_METADATA_BYTES } from '../src/core/event.js';
import { NATS_PUBLISH_BUDGET, protoSizeEstimate } from '../src/core/proto-size.js';
import { addBreadcrumb, setContext, setTag, setTenant, setUser } from '../src/core/scope.js';
import { metadataWireBytes } from '../src/core/serialize.js';
import type { CoreOptions, Runtime, SentinelEvent } from '../src/core/types.js';
import { commit } from './helpers/commit.js';
import { resetPipeline, setup, TURBOPACK_CHUNK } from './helpers/pipeline.js';

const HERE = dirname(fileURLToPath(import.meta.url));
const FIXTURES = join(HERE, 'fixtures');
const ESTIMATES_DIR = join(HERE, 'fixture-estimates', 'golden');
const NEVER_TOP_LEVEL = ['source', 'project_key', 'project_id', 'fingerprint_override'];

let uuidCounter = 0;
beforeEach(() => {
  resetPipeline();
  uuidCounter = 0;
  vi.spyOn(globalThis.crypto, 'randomUUID').mockImplementation(
    () => `00000000-0000-4000-8000-${String(++uuidCounter).padStart(12, '0')}` as `${string}-${string}-${string}-${string}-${string}`,
  );
  vi.useFakeTimers({ now: Date.UTC(2026, 8, 16, 12, 0, 0), toFake: ['Date'] });
});
afterEach(() => {
  vi.useRealTimers();
});

/** Capture through a fresh client and return the one event it produced, written to tests/fixtures/<name>.json. */
function emit(name: string, run: () => void, options: CoreOptions = {}, runtime: Runtime = 'browser'): SentinelEvent {
  const p = setup(options, runtime);
  run();
  const events = p.events();
  expect(events, `${name}: exactly one event`).toHaveLength(1);
  const event = events[0] as SentinelEvent;
  for (const key of NEVER_TOP_LEVEL) expect(event, `${name}: no top-level ${key}`).not.toHaveProperty(key);
  commit(join(FIXTURES, `${name}.json`), event);
  commit(join(ESTIMATES_DIR, `${name}.json`), { protoSizeEstimate: protoSizeEstimate(event as unknown as Record<string, unknown>) });
  return event;
}

function withStack(message: string, stack: string[], name = 'Error'): Error {
  const err = new Error(message);
  err.name = name;
  err.stack = [`${name}: ${message}`, ...stack].join('\n');
  return err;
}

const PAGE_CHUNK = 'https://app/_next/static/chunks/app/page-9b0d4e.js';

describe('§11 fixtures: generated from the pipeline and committed for the Go test', () => {
  it('fixture: a V8 stack', () => {
    const event = emit('v8-stack', () => {
      captureException(
        withStack(
          "Cannot read properties of undefined (reading 'id')",
          [`    at render (${PAGE_CHUNK}:12:34)`, `    at ${PAGE_CHUNK}:1:2`, '    at Module._compile (node:internal/modules/cjs/loader:1256:14)', '    at fn (native)'],
          'TypeError',
        ),
      );
    });
    expect(event.error_class).toBe('TypeError');
    expect(event.stacktrace.map((f) => f.in_app)).toEqual([true, true, false, false]);
  });

  it('fixture: a SpiderMonkey stack', () => {
    const err = new Error('render failed');
    err.stack = [`render@${PAGE_CHUNK}:12:34`, `@${PAGE_CHUNK}:1:2`, 'promiseReactionJob@[native code]'].join('\n');
    const event = emit('spidermonkey-stack', () => captureException(err));
    expect(event.stacktrace).toEqual([
      { file: PAGE_CHUNK, line: 12, column: 34, function: 'render', in_app: true },
      { file: PAGE_CHUNK, line: 1, column: 2, function: '<anonymous>', in_app: true },
      { file: '', function: 'promiseReactionJob', in_app: false },
    ]);
  });

  it('fixture: a stackless non-Error', () => {
    const event = emit('stackless-non-error', () => captureException({ code: 42, reason: 'quota' }));
    expect(event).toMatchObject({ error_class: 'NonError', message: '{"code":42,"reason":"quota"}', stacktrace: [] });
  });

  it('fixture: a captureMessage', () => {
    const event = emit('capture-message', () => captureMessage('cache miss storm', { level: 'warning' }));
    expect(event).toMatchObject({ error_class: 'Message', stacktrace: [], level: 'warning' });
  });

  it('fixture: a 20 000-char message cut on a code-point boundary', () => {
    const event = emit('message-cut-code-point', () => captureException(withStack('€'.repeat(20_000), [`    at render (${PAGE_CHUNK}:1:1)`])));
    expect(Buffer.byteLength(event.message)).toBe(MAX_MESSAGE_BYTES - 1);
    expect(event.message).toBe('€'.repeat(3333));
    expect(event.metadata.truncated).toEqual(['message']);
  });

  it('fixture: a 100 KiB component stack', () => {
    const componentStack = '\n    at Page (webpack-internal:///(app-pages-browser)/./src/app/page.tsx:12:5)'.repeat(1400);
    expect(Buffer.byteLength(componentStack)).toBeGreaterThanOrEqual(100 * 1024);
    const event = emit('component-stack-100kib', () => captureException(withStack('boundary', [`    at Page (${PAGE_CHUNK}:2:2)`]), { contexts: { react: { componentStack } } }));
    expect(Buffer.byteLength(event.metadata.react_component_stack as string)).toBeLessThanOrEqual(MAX_COMPONENT_STACK_BYTES);
    expect(event.metadata.truncated).toEqual(['react_component_stack']);
  });

  it('fixture: a node_modules frame', () => {
    const event = emit('node-modules-frame', () =>
      captureException(
        withStack('hook order', ['    at useState (/srv/app/node_modules/react/cjs/react.production.js:1:1)', `    at Page (${PAGE_CHUNK}:3:4)`]),
      ),
    );
    expect(event.stacktrace.map((f) => f.in_app)).toEqual([false, true]);
  });

  it('fixture: a Turbopack <16-hex>.js frame', () => {
    const event = emit('turbopack-chunk-frame', () => captureException(withStack('hydration', [`    at onClick (${TURBOPACK_CHUNK}:1:4821)`])));
    expect(event.stacktrace).toEqual([{ file: TURBOPACK_CHUNK, line: 1, column: 4821, function: 'onClick', in_app: true }]);
  });

  it('fixture: the V8 form `at async fn`', () => {
    const event = emit('v8-form-async', () => captureException(withStack('async', [`    at async loadPage (${PAGE_CHUNK}:5:6)`])));
    expect(event.stacktrace[0]?.function).toBe('loadPage');
  });

  it('fixture: the V8 form `at new Foo`', () => {
    const event = emit('v8-form-new', () => captureException(withStack('constructor', [`    at new Widget (${PAGE_CHUNK}:7:8)`])));
    expect(event.stacktrace[0]?.function).toBe('Widget');
  });

  it('fixture: the V8 form `at Object.<anonymous>`', () => {
    const event = emit('v8-form-object-anonymous', () =>
      captureException(withStack('module scope', ['    at Object.<anonymous> (/app/.next/server/app/page.js:9:10)'])),
    );
    expect(event.stacktrace[0]).toEqual({ file: '/app/.next/server/app/page.js', line: 9, column: 10, function: 'Object.<anonymous>', in_app: true });
  });

  it('fixture: the V8 form `at fn [as alias]`', () => {
    const event = emit('v8-form-as-alias', () => captureException(withStack('alias', [`    at handler [as onClick] (${PAGE_CHUNK}:11:12)`])));
    expect(event.stacktrace[0]?.function).toBe('handler');
  });

  it('fixture: the V8 eval form taking the outer location', () => {
    const event = emit('v8-form-eval-outer-location', () =>
      captureException(withStack('eval', [`    at eval (eval at outer (${PAGE_CHUNK}:13:14), <anonymous>:1:1)`])),
    );
    expect(event.stacktrace[0]).toEqual({ file: PAGE_CHUNK, line: 13, column: 14, function: 'eval', in_app: true });
  });

  it('fixture: a traceparent with flags 01', () => {
    const event = emit('traceparent-flags-01', () =>
      captureException(withStack('traced', [`    at fetchOrders (${PAGE_CHUNK}:3:3)`]), { traceparent: '00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01' }),
    );
    expect(event).toMatchObject({ trace_id: '4bf92f3577b34da6a3ce929d0e0e4736', span_id: '00f067aa0ba902b7', trace_flags: 1 });
  });

  it('fixture: a traceparent with flags 10 carrying trace_flags 16 (the hex radix)', () => {
    const event = emit('traceparent-flags-10', () =>
      captureException(withStack('traced', [`    at fetchOrders (${PAGE_CHUNK}:3:3)`]), { traceparent: '00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-10' }),
    );
    expect(event.trace_flags).toBe(16);
  });

  it('fixture: a PII object with an array (objects scrubbed recursively, the array not descended — Go parity)', () => {
    const event = emit('pii-object-with-array', () =>
      captureException(withStack('login', [`    at submit (${PAGE_CHUNK}:4:4)`]), {
        metadata: {
          password: 'hunter2',
          author: 'me',
          nested: { api_key: 'k', safe: 'kept' },
          items: [{ password: 'in-array' }],
          request_id: 'req_1',
        },
      }),
    );
    expect(event.metadata).toMatchObject({
      password: '[FILTERED]',
      author: '[FILTERED]',
      nested: { api_key: '[FILTERED]', safe: 'kept' },
      items: [{ password: 'in-array' }],
      request_id: 'req_1',
    });
  });

  it('fixture: an environment needing normalisation', () => {
    const event = emit('environment-normalised', () => captureException(withStack('env', [`    at boot (${PAGE_CHUNK}:5:5)`])), { environment: 'Pre Prod', release: '2.34.0' });
    expect(event.environment).toBe('pre-prod');
    expect(event.release_version).toBe('2.34.0');
  });

  it("fixture: the near-the-cap metadata — under 65 536 by JSON.stringify's count, over it by the validator's; html removed", () => {
    const html = ('<' + 'p'.repeat(24)).repeat(2000) + '\u2028';
    const pad = 'y'.repeat(14 * 1024 + 1000);
    const preShrink = { html, pad, request_id: 'req_1', runtime: 'browser' };
    const naive = Buffer.byteLength(JSON.stringify(preShrink));
    const goRule = metadataWireBytes(JSON.stringify(preShrink));
    expect(naive).toBeLessThan(MAX_METADATA_BYTES);
    expect(goRule).toBeGreaterThan(MAX_METADATA_BYTES);
    const event = emit('metadata-near-the-cap', () => captureException(withStack('near the cap', [`    at render (${PAGE_CHUNK}:6:6)`]), { metadata: { html, pad, request_id: 'req_1' } }));
    expect(event.metadata.html).toBeUndefined();
    expect(event.metadata.truncated_keys).toEqual(['html']);
    expect(metadataWireBytes(JSON.stringify(event.metadata))).toBeLessThanOrEqual(MAX_METADATA_BYTES);
  });

  it('fixture: rich typed context (node runtime, no {{auto}}) — every typed field in its place, metadata carries none of it', () => {
    const event = emit(
      'v2-rich-context',
      () => {
        setUser({ id: 'usr_1', username: 'ada', email: 'ada@example.com' });
        setTenant('org_a');
        setTag('feature', 'chats');
        setContext('ok', { a: 1 });
        addBreadcrumb({ message: 'clicked save', category: 'ui.click' });
        captureException(withStack('rich context', [`    at render (${PAGE_CHUNK}:7:7)`]));
      },
      {},
      'node',
    );
    expect(event.user).toEqual({ id: 'usr_1', username: 'ada', email: 'ada@example.com' });
    expect(event.tags).toEqual({ feature: 'chats', tenant_id: 'org_a' });
    expect(event.contexts).toEqual({ ok: { a: 1 } });
    expect(event.breadcrumbs).toHaveLength(1);
    expect(event.level).toBe('error');
    expect(event.sdk).toEqual({ name: 'sentinel.javascript.node', version: expect.any(String) });
    expect(event.metadata).not.toHaveProperty('user_id');
    expect(event.metadata).not.toHaveProperty('tenant_id');
    expect(event.metadata).not.toHaveProperty('feature');
  });

  it('fixture: a hostile beforeSend cannot make the ingestor 400 the event (spec §3.8, node runtime)', () => {
    const event = emit(
      'v2-hostile-before-send',
      () => {
        setContext('ok', { a: 1 });
        addBreadcrumb({ message: 'one' });
        captureException(withStack('hostile', [`    at render (${PAGE_CHUNK}:8:8)`]));
      },
      {
        beforeSend: (built) =>
          ({
            ...built,
            logger: 5,
            dist: {},
            source: [],
            exception: 'x',
            project_key: 7,
            fingerprint_override: 'yes',
            LEVEL: 7,
            Tags: 'x',
            environment: 42,
            release_version: {},
            fingerprint: 'f'.repeat(65),
            trace_id: 5,
            trace_flags: -1,
            stacktrace: built.stacktrace.map((f, i) => (i === 0 ? { ...f, line: 1e12 } : f)),
            contexts: { ...built.contexts, when: new Date(), url: new URL('https://h/p'), arr: { toJSON: () => [1] } },
            breadcrumbs: (built.breadcrumbs ?? []).map((b, i) => (i === 0 ? { ...b, data: new URL('https://h/p') } : b)),
            request: { headers: { a: 1 } },
            toJSON: () => ({ hacked: true }),
          }) as unknown as SentinelEvent,
      },
      'node',
    );
    expect(event).not.toHaveProperty('logger');
    expect(event).not.toHaveProperty('dist');
    expect(event).not.toHaveProperty('source');
    expect(event).not.toHaveProperty('exception');
    expect(event).not.toHaveProperty('project_key');
    expect(event).not.toHaveProperty('fingerprint_override');
    expect(event).not.toHaveProperty('LEVEL');
    expect(event).not.toHaveProperty('Tags');
    expect(event.environment).not.toBe(42);
    expect(event).not.toHaveProperty('release_version');
    expect(event).not.toHaveProperty('fingerprint');
    expect(event).not.toHaveProperty('trace_id');
    expect(event).not.toHaveProperty('trace_flags');
    expect(event.stacktrace[0]?.line).toBeUndefined();
    expect(event.contexts).toEqual({ ok: { a: 1 } });
    expect(event.breadcrumbs?.[0]?.data).toBeUndefined();
    expect(event.request).toBeUndefined();
  });

  it('fixture: every map-shaped field maxed out with tiny content — the +8-per-entry map overhead (spec §11.2, C9, round-8 finding sdkjs-rc-spec-estimate-vs-proto-not-gated-r8)', () => {
    const headers: Record<string, string> = {};
    const env: Record<string, string> = {};
    for (let i = 0; i < 64; i++) {
      headers[`h${i}`] = 'x'.repeat(150);
      env[`e${i}`] = 'x'.repeat(150);
    }
    const event = emit(
      'v2-estimate-numbers',
      () => {
        for (let i = 0; i < 50; i++) setTag(`k${i}`, 'x'.repeat(190));
        captureException(withStack('map entries', [`    at compute (${PAGE_CHUNK}:9:9)`]), { request: { headers, env } });
      },
      {},
      'node',
    );
    expect(Object.keys(event.tags ?? {}).length).toBeGreaterThanOrEqual(50);
    expect(Object.keys(event.request?.headers ?? {}).length).toBeGreaterThan(0);
    expect(Object.keys(event.request?.env ?? {}).length).toBeGreaterThan(0);
  });

  it('fixture: 40 multi-byte tags — utf8Bytes over the skeleton and the +8-per-entry map overhead (spec §11.2, C9, round-8 finding sdkjs-rc-spec-estimate-vs-proto-not-gated-r8)', () => {
    const event = emit(
      'v2-estimate-strings',
      () => {
        for (let i = 0; i < 40; i++) setTag(`t${String(i).padStart(2, '0')}`, '日本語🎉'.repeat(3));
        captureException(withStack('multi-byte tags', [`    at render (${PAGE_CHUNK}:10:10)`]));
      },
      {},
      'node',
    );
    expect(Object.keys(event.tags ?? {}).length).toBeGreaterThanOrEqual(40);
  });

  it("fixture: the NATS publish shed's own worked example, post-shed and near the budget (spec §4.6 round 7's case, §11.2, C9)", () => {
    const event = emit(
      'v2-publish-bound',
      () => {
        for (let i = 0; i < 32; i++) addBreadcrumb({ message: `${i}`, data: { a: Array(2030).fill(0) } });
        captureException(withStack('publish bound', [`    at fetchAll (${PAGE_CHUNK}:11:11)`]), { metadata: { a: Array(32_700).fill(0) } });
      },
      { maxBreadcrumbs: 100 },
      'node',
    );
    const estimate = protoSizeEstimate(event as unknown as Record<string, unknown>);
    expect(estimate).toBeLessThanOrEqual(NATS_PUBLISH_BUDGET);
    expect(event.metadata.truncated).toContain('breadcrumbs');
    expect((event.breadcrumbs?.length ?? 0)).toBeLessThan(32);
  });

  it('the committed set: ≥ 13 files, each a parseable event with no top-level source / project_key / project_id / fingerprint_override', () => {
    const files = readdirSync(FIXTURES).filter((f) => f.endsWith('.json'));
    expect(files.length).toBeGreaterThanOrEqual(13);
    for (const file of files) {
      const event = JSON.parse(readFileSync(join(FIXTURES, file), 'utf8')) as Record<string, unknown>;
      for (const key of NEVER_TOP_LEVEL) expect(event, `${file}: ${key}`).not.toHaveProperty(key);
      expect(event.platform, file).toBe('javascript');
      expect(typeof event.event_id, file).toBe('string');
    }
  });
});
